definition.script:
pipeline {
  agent any

  tools {
    nodejs 'NodeJS 20'
  }

  environment {
    PROJECT_DIR = '/workspace/bmp'
    NODE_ENV    = 'test'
    CI          = 'true'
    PATH        = "/var/jenkins_home/tools/jenkins.plugins.nodejs.tools.NodeJSInstallation/NodeJS 20/bin:/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin:${env.PATH}"
  }

  options {
    timeout(time: 30, unit: 'MINUTES')
    buildDiscarder(logRotator(numToKeepStr: '10'))
    disableConcurrentBuilds()
  }

  stages {

    stage('Verify Workspace') {
      steps {
        sh '''
          echo "=== Jenkins Build #${BUILD_NUMBER} ==="
          echo "Node: $(node --version)"
          echo "NPM:  $(npm --version)"
          ls /workspace/bmp/
        '''
      }
    }

    stage('CI Backend — Install') {
      steps {
        sh '''
          echo "Installing backend dependencies..."
          cd /workspace/bmp/backend
          npm install --prefer-offline
          echo "Done"
        '''
      }
    }

    stage('CI Backend — Unit Tests + Coverage') {
      steps {
        sh '''
          echo "Running backend unit tests (Jest)..."
          cd /workspace/bmp/backend
          npm test -- --forceExit --runInBand
          echo "Backend tests complete"
        '''
      }
      post {
        always {
          junit testResults: '/workspace/bmp/backend/junit.xml', allowEmptyResults: true
          publishHTML(target: [
            allowMissing: true,
            alwaysLinkToLastBuild: true,
            keepAll: true,
            reportDir: '/workspace/bmp/backend/coverage/lcov-report',
            reportFiles: 'index.html',
            reportName: 'Backend Coverage Report'
          ])
          archiveArtifacts artifacts: '/workspace/bmp/backend/coverage/lcov.info', allowEmptyArchive: true
        }
        success { echo 'Backend tests PASSED' }
        failure { error 'Backend tests FAILED — stopping pipeline' }
      }
    }

    stage('CI Frontend — Install') {
      steps {
        sh '''
          echo "Installing frontend dependencies..."
          cd /workspace/bmp/frontend
          npm install --prefer-offline
          npm install terser --save-dev --prefer-offline
          echo "Done"
        '''
      }
    }

    stage('CI Frontend — Unit Tests + Coverage') {
      steps {
        sh '''
          echo "Running frontend unit tests (Vitest)..."
          cd /workspace/bmp/frontend
          npx vitest run --coverage --reporter=verbose --reporter=junit --outputFile=junit.xml
          echo "Frontend tests complete"
        '''
      }
      post {
        always {
          junit testResults: '/workspace/bmp/frontend/junit.xml', allowEmptyResults: true
          publishHTML(target: [
            allowMissing: true,
            alwaysLinkToLastBuild: true,
            keepAll: true,
            reportDir: '/workspace/bmp/frontend/coverage',
            reportFiles: 'index.html',
            reportName: 'Frontend Coverage Report'
          ])
        }
        success { echo 'Frontend tests PASSED' }
        failure { error 'Frontend tests FAILED — stopping pipeline' }
      }
    }

    stage('CI Frontend — Production Build') {
      steps {
        sh '''
          echo "Building frontend production bundle..."
          cd /workspace/bmp/frontend
          VITE_API_URL=http://localhost:5000/api npm run build
          echo "Build complete"
        '''
      }
      post {
        success {
          archiveArtifacts artifacts: '/workspace/bmp/frontend/dist/**', allowEmptyArchive: true
          echo 'Frontend build artifact archived'
        }
      }
    }

    stage('Summary') {
      steps {
        sh '''
          echo ""
          echo "=================================================="
          echo "  CI/CD PIPELINE COMPLETE — Build #${BUILD_NUMBER}"
          echo "  Backend  : 815 Jest tests + coverage report"
          echo "  Frontend : 80 Vitest tests + production build"
          echo "=================================================="
        '''
      }
    }

  }

  post {
    success { echo 'Pipeline SUCCESS' }
    failure { echo 'Pipeline FAILED' }
    always  { cleanWs(cleanWhenSuccess: true, cleanWhenFailure: false) }
  }
}
